#pragma once

#include <array>
#include <filesystem>
#include <string>
#include <vector>

#include "util/Vec3.h"

// A missile type's maximum launch range, Rmax: the farthest range at which
// the type's own flight model, launched from the shooter's speed and
// altitude, still reaches a target that does not maneuver (Dantas et al.,
// "Weapon Engagement Zone Maximum Launch Range Estimation Using a Deep
// Neural Network", arXiv:2111.04474). Generated by tools/drivers/launch_zone.cpp
// into data/missiles/<id>/fit/launch_zone.json, read-only afterwards. See
// REFERENCE.md - Launch zone.
//
// Co-altitude: the target's altitude is taken as the shooter's.

// The launch conditions the table is indexed on.
struct LaunchGeometry {
    double shooterAltitudeFt = 0.0;
    double shooterMach = 0.0;
    double targetMach = 0.0;
    // Where the shooter sits as seen from the target, from the target's tail,
    // degrees in (-180, 180]: 0 = a tail chase, +/-180 = head-on.
    double aspectDeg = 0.0;
    // Where the target sits off the shooter's nose, degrees, >= 0. A target
    // on the other side is the mirror image, so the aspect's sign flips with
    // it.
    double offBoresightDeg = 0.0;
    double rangeFt = 0.0;
};

class LaunchZone {
public:
    // Axis order of the table: rmax is stored with the last axis varying
    // fastest.
    static constexpr int kAxes = 5;
    static constexpr std::array<const char*, kAxes> kAxisNames = {
        "shooter_altitude_ft", "shooter_mach", "target_mach", "aspect_deg", "off_boresight_deg"};
    static constexpr int kAspectAxis = 3;
    static constexpr int kOffBoresightAxis = 4;

    LaunchZone(std::array<std::vector<double>, kAxes> axes, std::vector<double> rmaxNmi,
               std::string missileFileHash);

    // Parses a launch_zone.json. Throws std::runtime_error naming the file
    // on anything malformed.
    static LaunchZone Load(const std::filesystem::path& file);

    // The table's geometry from positions (ft) and ground velocities (ft/s)
    // in the world frame (y up). Horizontal angles only; altitude and Mach
    // from the shooter's height in a standard atmosphere offset by
    // temperatureOffsetC.
    static LaunchGeometry Geometry(const Vec3& shooterPos, const Vec3& shooterVel, const Vec3& targetPos,
                                   const Vec3& targetVel, double temperatureOffsetC);

    // Rmax in feet: multilinear in all five axes, clamped to the table's
    // edges.
    double RmaxFt(const LaunchGeometry& geometry) const;

    const std::array<std::vector<double>, kAxes>& Axes() const { return axes_; }
    const std::vector<double>& RmaxNmi() const { return rmaxNmi_; }

    // The hash of the missile.json the table was generated from.
    const std::string& MissileFileHash() const { return missileFileHash_; }

    // 64-bit FNV-1a of a file's bytes with carriage returns dropped (so a
    // CRLF checkout hashes the same), as 16 hex digits.
    static std::string FileHash(const std::filesystem::path& file);

private:
    std::array<std::vector<double>, kAxes> axes_;
    std::vector<double> rmaxNmi_;
    std::string missileFileHash_;
};
